  "tips.priceFloor": "હંમેશા તમારી ખર્ચ મર્યાદાથી વધુ ભાવ રાખો — કાચો માલ, તમારો સમય અને પ્લેટફોર્મ ફી — મંદીના મહિનામાં પણ.",
  "tips.trackIncome": "દરેક વેચાણ નોંધો, નાનું હોય તો પણ. એક સરળ આવકની નોંધ તમને નબળી મોસમનું આયોજન કરવામાં અને લોન માટે કમાણી સાબિત કરવામાં મદદ કરે છે.",
  "tips.bulkOrders": "જથ્થાબંધ અને સંસ્થાકીય ઓર્ડર સ્થિર રીતે અને અગાઉથી ચૂકવણી કરે છે. તમારી ક્ષમતા અને તૈયારીનો સમય અપડેટ રાખો જેથી ખરીદદારો તમને શોધી શકે.",
  "tips.photoQuality": "સ્પષ્ટ, સારા પ્રકાશવાળા અને અનેક ખૂણાઓથી લીધેલા ફોટા સાથેની યાદીઓ ઝડપથી વેચાય છે. કુદરતી પ્રકાશ ફ્લેશ કરતાં વધુ સારો કામ કરે છે.",
  "tips.respondFast": "તમે એક દિવસમાં પ્રશ્નોના જવાબ આપો ત્યારે ખરીદદારો ઓર્ડર પૂરો કરે તેવી શક્યતા વધુ હોય છે.",
  "tips.saveSavings": "દરેક ચુકવણીનો થોડો ભાગ બચત તરીકે અલગ રાખો — 5% પણ ભેગું થઈને ઓર્ડર વચ્ચેના સમયમાં તમને મદદરૂપ થાય છે.",
  "tips.giPremium": "GI ટેગ મૂળસ્થાનનો પુરાવો છે જેના પર ખરીદદારો વિશ્વાસ કરે છે. પ્રમાણિત વસ્તુઓની કિંમત ઘણી વખત વધુ રાખી શકાય છે — તમારી વસ્તુની કિંમત ઓછી ન આંકો.",
  "tips.restockEarly": "કાચો માલ ખૂટે તે પહેલાં જ ફરીથી મંગાવવાનું શરૂ કરો, ખાસ કરીને તહેવાર અને લગ્નની મોસમ પહેલાં જ્યારે માંગ વધે છે.",
  "tips.clusterSupport": "તમારા ક્લસ્ટર સંયોજક જથ્થાબંધ સામગ્રી ખરીદી અને તાલીમમાં મદદ કરી શકે છે — સમસ્યા ગંભીર બને તે પહેલાં જ સંપર્ક કરો.",
  "tips.storySells": "વાર્તાવાળી વસ્તુઓ માટે ખરીદદારો વધુ ચૂકવે છે. તમારી ટેકનિક કે કલાના ઇતિહાસ વિશે એક ટૂંકી નોંધ તમારી યાદીમાં ઉમેરો.",
