  "pdp.care.frame": "કાચ પાછળ ફ્રેમ કરો. ભીની દીવાલો અને સીધા તડકાથી દૂર રાખો.",
  "pdp.care.default": "કાળજીથી સાચવો. નરમ સૂકા કપડાથી હળવેથી સાફ કરો.",
  "pdp.review.1.title": "ફોટા કરતાં પણ સુંદર",
  "pdp.review.1.body": "{craft}નું કામ નજીકથી વધુ બારીક છે. નાની અસમાનતાઓ બતાવે છે કે તે હાથે બનેલું છે. ખૂબ કાળજીથી પેક કરેલું હતું.",
  "pdp.review.2.title": "દરેક રૂપિયાની કિંમત",
  "pdp.review.2.body": "પૈસા સીધા {artisan}ને જાય છે એ જાણીને નિર્ણય સરળ બન્યો. સંગ્રહાલય જેવી ગુણવત્તા.",
  "pdp.review.3.title": "સુંદર, થોડું મોડું આવ્યું",
  "pdp.review.3.body": "અંદાજ કરતાં ત્રણ દિવસ મોડું આવ્યું, પણ કારીગરે સંદેશ મોકલીને કારણ જણાવ્યું. વસ્તુ પોતે અદ્ભુત છે.",
  "pdp.review.4.title": "મહોર તપાસી, બધું અસલ",
  "pdp.review.4.body": "મળ્યા પછી પ્રમાણિકતાનો રેકોર્ડ તપાસ્યો અને તે યાદી સાથે બરાબર મળતો હતો. આખરે ઑનલાઇન હસ્તકલા ખરીદી પર ભરોસો થયો.",
  "pdp.review.5.title": "સારું, પણ માપ તપાસો",
  "pdp.review.5.body": "ઉત્તમ કારીગરી, પણ ધાર્યા કરતાં નાનું. ઓર્ડર પહેલાં વિગતોના કોષ્ટકમાં માપ વાંચી લો.",
  "pdp.qa.1.q": "આ હાથે બનાવેલું છે કે મશીનથી?",
  "pdp.qa.1.a": "સંપૂર્ણપણે હાથે બનાવેલું. જીઆઈ ટેગ અને પ્રમાણિકતા મહોર બંને તકનીકની પુષ્ટિ કરે છે.",
  "pdp.qa.2.q": "શું હું અલગ રંગ માંગી શકું?",
  "pdp.qa.2.aMto": "હા, ઓર્ડર પર બનતી વસ્તુઓમાં ફેરફાર થઈ શકે છે — ઓર્ડરની નોંધમાં લખો.",
  "pdp.qa.2.aReady": "આ તૈયાર સ્ટોકની વસ્તુ છે, તેથી રંગ બતાવ્યા મુજબ જ છે. ખાસ ઓર્ડર માટે કારીગરને સંદેશ મોકલો.",
  "pdp.qa.3.q": "મોકલવા માટે તે કેવી રીતે પેક થાય છે?",
  "pdp.qa.3.a": "કાપડમાં, પછી બબલ રેપમાં વીંટાળીને બે સ્તરવાળા બૉક્સમાં. નાજુક વસ્તુઓ માટે ખાસ ક્રેટ.",
  "pdp.qa.4.q": "ધોયા પછી રંગ ઝાંખા પડશે?",
  "pdp.qa.4.a": "કુદરતી રંગ વર્ષો સાથે થોડા હળવા થાય છે, જે સ્વાભાવિક છે. રંગ જાળવવા સંભાળની સૂચનાઓ અનુસરો.",
  "pdp.storefront.bio": "{name} {district}માં {craft}નું કામ કરે છે અને સીધું ખરીદદારોને વેચે છે.",
