  "learn.PHOTO.title": "સારા ફોટા લો",
  "learn.PHOTO.c1": "દિવસના પ્રકાશમાં, દરવાજા કે બારી પાસે ફોટા લો. ટ્યુબ લાઇટ ટાળો.",
