  "learn.STORY.title": "તમારી વાર્તા કહો",
  "learn.STORY.c1": "ખરીદનારા વધુ ચૂકવે છે જ્યારે તેમને ખબર હોય કે વસ્તુ કોણે અને કેવી રીતે બનાવી.",
  "learn.STORY.c2": "તમારું નામ, ગામ અને તમને કારીગરી કોણે શીખવી તે કહો.",
  "learn.STORY.c3": "એક વસ્તુ બનાવવામાં કેટલા દિવસ લાગે છે અને કયો સામાન વાપરો છો તે કહો.",
  "learn.STORY.practice": "તમારી એક વસ્તુ વિશે ટૂંકી અવાજ વાર્તા રેકોર્ડ કરો.",
  "learn.STORY.q": "તમારી વાર્તાએ ખરીદનારને શું કહેવું જોઈએ?",
  "learn.STORY.a1": "કોણે અને કેવી રીતે તે બનાવ્યું",
  "learn.STORY.a2": "ફક્ત કિંમત",
  "learn.STORY.a3": "તમારો ફોન નંબર",
  "learn.PRICE.title": "યોગ્ય કિંમત નક્કી કરો",
  "learn.PRICE.c1": "એક વસ્તુના સામાનની કિંમત ઉમેરો.",
  "learn.PRICE.c2": "તમે કામ કરેલા દરેક દિવસ માટે યોગ્ય મજૂરી ઉમેરો.",
  "learn.PRICE.c3": "કલાકૃતિની કિંમત માર્ગદર્શિકા સૌથી ઓછી કિંમત બતાવે છે જે તો પણ તમને યોગ્ય રીતે ચૂકવે.",
  "learn.PRICE.q": "સામાનની કિંમત ₹300 હતી અને તમે 2 દિવસ કામ કર્યું. યોગ્ય કિંમત શું છે?",
  "learn.PRICE.a1": "ફક્ત સામાન માટે ₹300",
  "learn.PRICE.a2": "ખરીદનાર જે આપે તે",
