  "learn.ORDERS.title": "ઓર્ડર સંભાળો",
  "learn.ORDERS.c1": "જ્યારે ખરીદનાર ઓર્ડર આપે છે, ત્યારે તમને સંદેશ મળે છે અને ઓર્ડર ઓર્ડર્સ હેઠળ દેખાય છે.",
  "learn.ORDERS.c2": "ફક્ત તે જ સ્વીકારો જે તમે બતાવેલી તારીખ સુધીમાં પૂરું કરી શકો.",
  "learn.ORDERS.c3": "જો સમયસર પૂરું ન કરી શકો, તો એપ મારફતે વહેલા ખરીદનારને જણાવો.",
  "learn.ORDERS.q": "એક ઓર્ડરમાં 5 દિવસમાં 50 વસ્તુઓ જોઈએ છે, પણ તમે 20 બનાવી શકો છો. તમે શું કરશો?",
