  "learn.PAYMENTS.title": "સુરક્ષિત રીતે ચુકવણી મેળવો",
  "learn.PAYMENTS.c1": "ખરીદનારા કલાકૃતિને ચૂકવે છે, અને પૈસા સીધા તમારા બેંક ખાતામાં જાય છે.",
  "learn.PAYMENTS.c2": "રસ્તામાં હોય એવા પૈસા હજુ તમારા ખાતામાં નથી. તે ડિલિવરી પછી આવે છે.",
  "learn.PAYMENTS.c3": "તમારા પોતાના પૈસા મેળવવા તમારે ક્યારેય કોઈને ચૂકવવું પડતું નથી.",
  "learn.PAYMENTS.q": "કોઈ તમને તમારી ચુકવણી છોડવા ₹500 ચૂકવવા કહે છે. તમે શું કરશો?",
  "learn.PAYMENTS.a1": "ના પાડો. તે છેતરપિંડી છે.",
  "learn.PAYMENTS.a2": "₹500 ચૂકવો",
