  "learn.SAFETY.c1": "ક્યારેય કોઈને તમારો OTP ન કહો, ભલે કોઈ કલાકૃતિ કે બેંકમાંથી હોવાનો દાવો કરે.",
  "learn.SAFETY.c2": "કલાકૃતિ ક્યારેય તમારો પિન કે પાસવર્ડ માંગશે નહીં.",
  "learn.SAFETY.c3": "જો કોઈ સંદેશ તાત્કાલિક હોય અને પૈસા કે કોડ માંગે, તો રોકાઓ અને તમે વિશ્વાસ કરો છો તેવા કોઈને પૂછો.",
  "learn.SAFETY.practice": "મોટેથી કહો: હું ક્યારેય મારો OTP શેર નહીં કરું. પછી નીચેના બટન પર ટેપ કરો.",
  "learn.SAFETY.q": "એક કૉલર તમને હમણાં જ મળેલો OTP માંગે છે. તમે શું કરશો?",
