  "caseStudies.dhamadka-ajrakh.rows.3.after": "સ્પેક્ટ્રોસ્કોપિક બોટનિકલ ઈન્ડિગો પ્રૂફ અને ક્રિપ્ટોગ્રાફિક NFC સીલ",
  "caseStudies.dhamadka-ajrakh.rows.4.dimension": "ચુકવણી પતાવટ",
  "caseStudies.dhamadka-ajrakh.rows.4.before": "ક્રેડિટ કન્સાઇનમેન્ટ પર 6 થી 9 મહિના વિલંબિત ચુકવણી",
  "caseStudies.dhamadka-ajrakh.rows.4.after": "કેરિયર સ્કેન પર સ્વચાલિત 48-કલાક એસ્ક્રો ચૂકવણી",
  "caseStudies.dhamadka-ajrakh.problem": "દાયકાઓથી, ધમાડકામાં કોમર્શિયલ ફાસ્ટ-ફેશન હાઉસ દ્વારા આયાત કરવામાં આવતા સિન્થેટિક કેમિકલ બ્લોક-પ્રિન્ટ્સે અધિકૃત હેન્ડ બ્લોક-પ્રિંટર્સને ગંભીર રીતે ઓછા કર્યા છે. રાસાયણિક અવેજીઓએ બજારોમાં 20% કિંમતે છલકાઇ, પરંપરાગત માસ્ટર્સને પ્રાચીન 16-તબક્કાની વનસ્પતિ પ્રતિકાર તકનીકોને પાતળું કરવા દબાણ કર્યું.",
  "caseStudies.dhamadka-ajrakh.intervention": "કલાકૃતિ દ્વારા, ધમાડકા ગિલ્ડે વાસ્તવિક ઈન્ડિગોફેરા ટિંક્ટોરિયા વાટ આથો અને બબૂલ અરેબિકા ગમ પ્રતિરોધકની સ્પેક્ટ્રોસ્કોપિક ચકાસણીનો અમલ કર્યો. દરેક ચોરાયેલી અને યાર્ડેજ લંબાઈને ક્લસ્ટર છોડતા પહેલા અપરિવર્તનશીલ Ed25519 ક્રિપ્ટોગ્રાફિક સીલ અને NFC QR ટેગ પ્રાપ્ત થાય છે.",
  "caseStudies.dhamadka-ajrakh.impact": "અધિકૃતતાની ચકાસણીએ ગિલ્ડને લક્ઝરી ડિઝાઇન હાઉસ અને વિદેશી સાંસ્કૃતિક મિશનને સીધા વેચવાની મંજૂરી આપી. ઘરની આવકમાં 3.37xનો વધારો થયો છે, જે 14 યુવા પ્રિન્ટરો માટે સામૂહિક કુદરતી ડાઈ સીડ બેંક અને એપ્રેન્ટિસશીપ ફંડની રચનાને સક્ષમ બનાવે છે.",
  "caseStudies.dhamadka-ajrakh.quote.text": "જ્યારે ખરીદદારો અમારા કાપડને સ્કેન કરે છે અને ઈન્ડિગો વૉટમાં અમારા હાથ જુએ છે, ત્યારે તેઓ સમજે છે કે શા માટે 16 તબક્કામાં ઉતાવળ કરી શકાતી નથી. કલાકૃતિએ અમારું સન્માન પાછું આપ્યું.",
  "caseStudies.dhamadka-ajrakh.quote.author": "ઈસ્માઈલ મોહમ્મદ ખત્રી",
  "caseStudies.dhamadka-ajrakh.quote.role": "માસ્ટર ક્રાફ્ટ્સમેન અને નેશનલ એવોર્ડી, ધમડકા",
