  "caseStudies.varanasi-kadwa.problem": "વારાણસીમાં માસ્ટર ઝરી વણકરો બહુ-સ્તરીય બજાર મધ્યસ્થીઓ પર નિર્ભર હતા જેમણે છૂટક માર્જિનના 35-40% જાળવી રાખ્યા હતા અને 9 મહિના સુધી ચૂકવણીમાં વિલંબ કર્યો હતો, જેના કારણે વણાટ પરિવારોને ચક્રીય ચોમાસાના દેવાની ફરજ પડી હતી.",
  "caseStudies.varanasi-kadwa.intervention": "કલાકૃતિના સંસ્થાકીય પ્રાપ્તિ કેન્દ્રએ રાજ્ય સમિટ હોસ્પિટાલિટી જૂથો અને કોર્પોરેટ ગિફ્ટિંગ કન્સોર્ટિયાને પરિવાર બંકર એસએચજી સાથે સીધા જ સામૂહિક બલ્ક ઓર્ડર્સ કરવાની મંજૂરી આપી હતી. લૂમ માઇલસ્ટોન કન્ફર્મેશન પર ડાયરેક્ટ ડીબીટી ટ્રાન્સફર સાથે પેમેન્ટ એસ્ક્રો ઓટોમેટેડ છે.",
  "caseStudies.varanasi-kadwa.impact": "ડિસ્પેચના 48 કલાકની અંદર કુલ ₹1.48 કરોડનું વિતરણ વણકર સુધી પહોંચ્યું. 86 પિટ-લૂમ્સ હવે 12-મહિનાના એડવાન્સ ચક્રમાં કાયમી ધોરણે બુક કરવામાં આવ્યા છે, જે મોસમી ગરીબીને સંપૂર્ણપણે દૂર કરે છે.",
  "caseStudies.varanasi-kadwa.quote.text": "ત્રણ પેઢીઓ સુધી, અમે ક્યારેય અંતિમ ખરીદનારનો ચહેરો જોયો નથી. હવે અમારું નામ અને લૂમ કોઓર્ડિનેટ દરેક સાડી સાથે મુસાફરી કરે છે જે અમે એકબીજાને જોડીએ છીએ.",
