  "caseStudies.bastar-lost-wax.problem": "અસ્થિર તાંબા અને જસતના સ્ક્રેપના ભાવે આદિવાસી ધોકરાના શિલ્પકારો માટે કાચું મીણ, માટી અને કાસ્ટિંગ ધાતુઓ અગાઉથી પરવડે તે લગભગ અશક્ય બનાવ્યું, જે માનવતાની સૌથી જૂની બિન-ફેરસ કાસ્ટિંગ વંશમાંથી એકને ભૂંસી નાખવાની ધમકી આપે છે.",
  "caseStudies.bastar-lost-wax.intervention": "પ્લેટફોર્મે સંસ્થાકીય સમિટ પ્રોક્યોરમેન્ટ કિટ્સ દ્વારા સમર્થિત કાચા માલની ઇન્વેન્ટરી ક્રેડિટ રજૂ કરી. શિલ્પકારો તેમની કારીગર એપ્લિકેશન પર પીગળેલા રેડવાની નોંધ કરે છે, જેમાં ભેળસેળ વગરના બેલ મેટલ એલોય સાબિત થાય છે.",
  "caseStudies.bastar-lost-wax.impact": "28 નવા આદિવાસી એપ્રેન્ટિસ કોંડાગાંવ ભઠ્ઠીઓમાં જોડાયા છે. બસ્તરના ખોવાયેલા મીણના શિલ્પો હવે વિશ્વભરની અગ્રણી સંસ્થાકીય લોબીઓ અને રાજદ્વારી ભેટો આપે છે.",
  "caseStudies.bastar-lost-wax.quote.text": "અમારા પૂર્વજો સાલના જંગલોમાંથી મીણનો ઉપયોગ કરતા હતા. કલાકૃતિ એ સુનિશ્ચિત કરે છે કે આપણી ભઠ્ઠીઓ ઋણના ડર વિના આગામી પેઢી માટે તેજસ્વી બને.",
